/** First-time content for NUFA Academy: courses, lessons, exam questions and the study library. Runs once; edit everything in admin. */
function acad_seed($conn) {
    $courses = array_merge(require __DIR__ . '/academy-content-a.php', require __DIR__ . '/academy-content-b.php', require __DIR__ . '/academy-content-c.php');
    $ci = $conn->prepare("INSERT INTO academy_courses (slug,title,level,category,summary,description,outcomes,duration,is_featured,sort_order) VALUES (?,?,?,?,?,?,?,?,?,?)");
    $li = $conn->prepare("INSERT INTO academy_lessons (course_id,sort_order,title,minutes,body) VALUES (?,?,?,?,?)");
    $qi = $conn->prepare("INSERT INTO academy_questions (course_id,question,opt_a,opt_b,opt_c,opt_d,correct,explanation) VALUES (?,?,?,?,?,?,?,?)");
    foreach ($courses as $n => $c) {
        $feat = !empty($c['featured']) ? 1 : 0; $o = $n + 1;
        $ci->bind_param("ssssssssii", $c['slug'], $c['title'], $c['level'], $c['category'], $c['summary'], $c['description'], $c['outcomes'], $c['duration'], $feat, $o);
        $ci->execute(); $cid = $conn->insert_id;
        foreach ($c['lessons'] as $i => [$t, $m, $b]) { $so = $i + 1; $li->bind_param("iisis", $cid, $so, $t, $m, $b); $li->execute(); }
        foreach ($c['questions'] as [$q, $opts, $ok, $ex]) {
            $pairs = []; foreach ($opts as $k => $t) $pairs[] = [$t, $k === $ok]; shuffle($pairs);   // do not leave every right answer in the same slot
            $opts = array_column($pairs, 0); $ok = (int)array_search(true, array_column($pairs, 1), true);
            $qi->bind_param("isssssis", $cid, $q, $opts[0], $opts[1], $opts[2], $opts[3], $ok, $ex); $qi->execute(); }
    }
    $ri = $conn->prepare("INSERT INTO academy_resources (title,provider,type,category,level,url,description,cost,verified_on,sort_order) VALUES (?,?,?,?,?,?,?,?,?,?)");
    foreach (acad_seed_resources() as $i => $r) {
        $v = !empty($r['v']) ? '2026-10-21' : null; $so = $i + 1;
        $ri->bind_param("sssssssssi", $r['t'], $r['p'], $r['type'], $r['cat'], $r['lvl'], $r['url'], $r['d'], $r['cost'], $v, $so);
        $ri->execute();
    }
}

